-- One-time update, guarded by the exact pre-update snapshot.
SET NAMES utf8mb4;
SET SESSION sql_mode='STRICT_ALL_TABLES,NO_ENGINE_SUBSTITUTION';
CREATE TEMPORARY TABLE sci_comuni_guard (ok INT NOT NULL CHECK(ok=1));
CREATE TEMPORARY TABLE sci_comuni_before LIKE cod_comuni;
-- Snapshot before update. Restore only into an empty table with original schema.

CREATE TEMPORARY TABLE sci_comuni_source (cod VARCHAR(80) PRIMARY KEY, des VARCHAR(80) NOT NULL, pr VARCHAR(80) NOT NULL) CHARACTER SET utf8mb4;
START TRANSACTION;
SELECT pk FROM cod_comuni ORDER BY pk FOR UPDATE;
UPDATE cod_comuni a JOIN sci_comuni_source s ON a.cod=s.cod SET a.des=s.des,a.pr=s.pr,a.lastupdate=NOW() WHERE BINARY a.des<>BINARY s.des OR BINARY a.pr<>BINARY s.pr;
COMMIT;
