INSERT INTO sci_comuni_guard SELECT IF((SELECT COUNT(*) FROM cod_comuni)=7980 AND (SELECT COUNT(*) FROM cod_comuni a JOIN sci_comuni_before b ON a.pk=b.pk WHERE BINARY a.`pk` <=> BINARY b.`pk` AND BINARY a.`cod` <=> BINARY b.`cod` AND BINARY a.`des` <=> BINARY b.`des` AND BINARY a.`pr` <=> BINARY b.`pr` AND BINARY a.`lastupdate` <=> BINARY b.`lastupdate`)=7980,1,0);
INSERT INTO cod_comuni (cod,des,pr,lastupdate) SELECT s.cod,s.des,s.pr,NOW() FROM sci_comuni_source s LEFT JOIN cod_comuni a ON a.cod=s.cod WHERE a.pk IS NULL ORDER BY s.cod;
INSERT INTO sci_comuni_guard SELECT IF(COUNT(*)=11294,1,0) FROM cod_comuni;
INSERT INTO sci_comuni_guard SELECT IF(COUNT(*)=11294,1,0) FROM cod_comuni a JOIN sci_comuni_source s ON BINARY a.cod=BINARY s.cod AND BINARY a.des=BINARY s.des AND BINARY a.pr=BINARY s.pr;
INSERT INTO sci_comuni_guard SELECT IF(COUNT(DISTINCT cod)=11294,1,0) FROM cod_comuni;
INSERT INTO sci_comuni_guard SELECT IF(COUNT(*)=7980,1,0) FROM cod_comuni a JOIN sci_comuni_before b ON a.pk=b.pk AND BINARY a.cod=BINARY b.cod;
